protected int findWrapPos(String text, int width, int startPos) {
    // Robustness: Input validation
    if (text == null) {
        throw new IllegalArgumentException("text cannot be null");
    }
    if (width <= 0) {
        throw new IllegalArgumentException("width must be positive");
    }
    if (startPos < 0 || startPos > text.length()) {
        throw new IllegalArgumentException("startPos must be within text bounds [0, text.length()]");
    }
    if (startPos == text.length()) {
        return -1; // Already at the end of the text, nothing to wrap
    }

    // Calculate the absolute end position for the current line segment
    int endPos = startPos + width;

    // If the entire remaining text fits within the width, no wrap needed
    if (endPos >= text.length()) {
        return -1;
    }

    int pos;

    // Priority 1: Check for explicit line breaks (newline or tab) within the wrap width
    // The comparison should be based on the length of the segment (pos - startPos)
    pos = text.indexOf('\n', startPos);
    if (pos != -1 && (pos - startPos) < width) {
        return pos + 1; // Return position *after* the newline
    }

    pos = text.indexOf('\t', startPos);
    if (pos != -1 && (pos - startPos) < width) {
        return pos + 1; // Return position *after* the tab
    }

    // Priority 2: Look for the last whitespace character before the calculated endPos
    // We search backwards from 'endPos' down to 'startPos'.
    // If no whitespace is found, we'll try to break the word.
    int wrapCandidatePos = -1; // Initialize with -1, meaning no suitable break found yet

    // Iterate backwards from endPos (or end of string if smaller) to startPos
    // We limit the search to the current 'width' segment.
    int searchLimit = Math.min(endPos, text.length() - 1); // Don't go past end of string

    for (pos = searchLimit; pos >= startPos; --pos) {
        char c = text.charAt(pos);
        if (Character.isWhitespace(c) && c != '\n' && c != '\t') { // Exclude \n and \t as they were handled
            wrapCandidatePos = pos;
            break; // Found the last whitespace, this is our preferred wrap point
        }
    }

    // If a whitespace was found within the allowed width, return its position
    if (wrapCandidatePos != -1) {
        return wrapCandidatePos;
    }

    // Priority 3: If no whitespace was found within 'width', break the word at 'endPos'.
    // If endPos is within a word, we find where that word actually ends.
    // This handles cases where a single word is longer than 'width'.
    pos = endPos;
    while (pos < text.length() && !Character.isWhitespace(text.charAt(pos))) {
        ++pos;
    }
    // If 'pos' reached the end of the text, it means the word extended to the end
    // and no further wrap is needed for the current segment.
    return pos == text.length() ? -1 : pos;
}
```

