import java.util.Objects; // For Objects.requireNonNull

protected int findWrapPos(String text, int width, int startPos) {
    // --- Robustness: Input Validation ---
    Objects.requireNonNull(text, "Text cannot be null");
    if (width < 0) {
        throw new IllegalArgumentException("Width cannot be negative: " + width);
    }
    if (startPos < 0) {
        throw new IllegalArgumentException("Start position cannot be negative: " + startPos);
    }
    if (startPos >= text.length()) {
        // If startPos is at or beyond the end of the text, there's nothing to wrap.
        return -1;
    }

    // --- Logical Flow ---

    // 1. Check for explicit line breaks (newline or tab) within the wrap width.
    // If a newline or tab is found, the line should break immediately after it.
    int pos;
    int maxSearchPos = Math.min(startPos + width, text.length());

    // Search for newline
    int newlinePos = text.indexOf('\n', startPos);
    if (newlinePos != -1 && newlinePos < maxSearchPos) {
        return newlinePos + 1;
    }

    // Search for tab
    int tabPos = text.indexOf('\t', startPos);
    if (tabPos != -1 && tabPos < maxSearchPos) {
        return tabPos + 1;
    }

    // 2. If the remaining text from startPos is shorter than or equal to the width,
    // it means this is the last "line" or the current segment perfectly fits.
    // In this case, no wrap is needed, so return -1.
    if (startPos + width >= text.length()) {
        return -1;
    }

    // 3. Look for the last whitespace character before `startPos + width`.
    // This aims to find a natural break point (word boundary).
    pos = startPos + width - 1; // Start searching from just before the potential chop point.

    // Search backwards for a space, newline, or carriage return.
    while (pos >= startPos) {
        char c = text.charAt(pos);
        if (Character.isWhitespace(c)) { // Using isWhitespace to cover space, tab, newline, etc.
            return pos; // Found a natural break point
        }
        --pos;
    }

    // 4. If no whitespace was found before `startPos + width` (i.e., a long word),
    // then force a break at `startPos + width`. However, if `startPos + width`
    // falls in the middle of a non-whitespace sequence, extend the break
    // to the end of that sequence to avoid splitting a word.
    pos = startPos + width; // Start from the initial chop point.

    // Move 'pos' forward until a whitespace character or end of string is found.
    while (pos < text.length()) {
        char c = text.charAt(pos);
        if (Character.isWhitespace(c)) {
            break; // Found a natural break point (e.g., end of a word)
        }
        ++pos;
    }

    // If 'pos' reached the end of the string, it means no more wraps are needed.
    // Otherwise, 'pos' is the break point.
    return (pos == text.length()) ? -1 : pos;
}
