public static String join(Object[] array, char separator, int startIndex, int endIndex) {
    if (array == null) {
        return null;
    }

    // Validate startIndex and endIndex
    if (startIndex < 0) {
        throw new IndexOutOfBoundsException("startIndex cannot be negative: " + startIndex);
    }
    if (endIndex > array.length) {
        throw new IndexOutOfBoundsException("endIndex cannot be greater than array length: " + endIndex + " > " + array.length);
    }
    if (startIndex > endIndex) {
        // As per existing logic and common utility expectations,
        // an empty string is returned if the range is invalid or empty.
        return EMPTY;
    }

    int noOfItems = (endIndex - startIndex);
    if (noOfItems <= 0) {
        return EMPTY;
    }

    // Improved StringBuilder capacity estimation
    // Estimate total length by summing lengths of all non-null elements
    // and adding space for separators.
    // This is an estimate, exact calculation is complex due to toString() overhead.
    // A reasonable initial capacity to reduce reallocations.
    int estimatedCapacity = 0;
    if (noOfItems > 0) {
        // If there's at least one item, estimate for it
        if (array[startIndex] != null) {
            estimatedCapacity += array[startIndex].toString().length();
        }
        // Estimate for remaining items and separators
        for (int i = startIndex + 1; i < endIndex; i++) {
            estimatedCapacity += 1; // For separator
            if (array[i] != null) {
                estimatedCapacity += array[i].toString().length();
            }
        }
    }
    // Add a small buffer for safety and potential variations
    estimatedCapacity = Math.max(16, estimatedCapacity); // Ensure a minimum reasonable capacity

    StringBuilder buf = new StringBuilder(estimatedCapacity);

    for (int i = startIndex; i < endIndex; i++) {
        if (i > startIndex) {
            buf.append(separator);
        }
        if (array[i] != null) {
            buf.append(array[i]);
        }
    }
    return buf.toString();
}
