public static String join(Object[] array, char separator, int startIndex, int endIndex) {
    if (array == null) {
        return null;
    }

    // Input validation for startIndex and endIndex
    if (startIndex < 0) {
        throw new IndexOutOfBoundsException("startIndex must not be negative, was: " + startIndex);
    }
    if (endIndex > array.length) {
        throw new IndexOutOfBoundsException("endIndex must not be greater than array.length, was: " + endIndex + ", array.length: " + array.length);
    }
    if (startIndex > endIndex) {
        // If startIndex is greater than endIndex, the effective range is empty.
        // Return empty string as no elements are to be joined.
        return EMPTY;
    }

    int noOfItems = (endIndex - startIndex);
    if (noOfItems <= 0) { // Handles cases where startIndex == endIndex
        return EMPTY;
    }

    // Estimate initial capacity more accurately to reduce reallocations.
    // Sum of lengths of all string representations + (number of separators).
    // Initialize with a reasonable default to avoid over-calculating if all elements are null.
    int estimatedCapacity = 0;
    for (int i = startIndex; i < endIndex; i++) {
        if (array[i] != null) {
            estimatedCapacity += array[i].toString().length();
        }
    }
    estimatedCapacity += (noOfItems - 1); // Add capacity for separators

    // Ensure minimum capacity, e.g., for empty elements or if initial calculation is too small.
    // A small buffer to start if calculated capacity is 0 (e.g., all nulls) or very small.
    if (estimatedCapacity < 16) {
        estimatedCapacity = 16;
    }

    StringBuilder buf = new StringBuilder(estimatedCapacity);

    for (int i = startIndex; i < endIndex; i++) {
        if (i > startIndex) { // Append separator before every element except the first one
            buf.append(separator);
        }
        if (array[i] != null) {
            buf.append(array[i]);
        }
    }
    return buf.toString();
}
