     * @param endIndex   the index to stop joining at (exclusive).
     * @return the joined String, or null if the input array is null.
     * @throws IndexOutOfBoundsException if startIndex is negative,
     *                                   or endIndex is greater than the array length,
     *                                   or startIndex is greater than array length (unless endIndex is also <= startIndex).
     */
    public static String join(Object[] array, char separator, int startIndex, int endIndex) {
        if (array == null) {
            return null;
        }

        // Validate startIndex and endIndex against array bounds
        if (startIndex < 0) {
            throw new IndexOutOfBoundsException("startIndex cannot be negative: " + startIndex);
        }
        if (endIndex > array.length) {
            throw new IndexOutOfBoundsException("endIndex cannot be greater than array length: " + endIndex + " > " + array.length);
        }
        if (startIndex > array.length) {
             // This case is typically covered by the above endIndex check for non-empty ranges,
             // but explicitly handling it for a single startIndex check for completeness.
             // If startIndex == array.length and endIndex == array.length, it's an empty range,
             // which is handled by noOfItems <= 0.
             // If startIndex > array.length, it's definitively out of bounds.
             throw new IndexOutOfBoundsException("startIndex cannot be greater than array length: " + startIndex + " > " + array.length);
        }


        int noOfItems = (endIndex - startIndex);
        if (noOfItems <= 0) {
            return EMPTY;
        }

        // Estimate initial capacity more robustly.
        // A simple heuristic: assume average element length is 16 and add space for separators.
        // This avoids accessing array[startIndex] before range validation.
        int estimatedCapacity = noOfItems * (16 + 1);
        StringBuilder buf = new StringBuilder(Math.max(estimatedCapacity, 16)); // Ensure a reasonable minimum capacity

        for (int i = startIndex; i < endIndex; i++) {
            if (i > startIndex) {
                buf.append(separator);
            }
            // Use Objects.toString() to safely convert any object to string, treating null as "null" string or an empty string.
            // Original logic explicitly skipped nulls, let's keep that behavior.
            if (array[i] != null) {
