public List getValues(final Option option, List externalDefaultValues) {
    // 1. Input validation: Ensure option is not null
    if (option == null) {
        // Log an error or throw an IllegalArgumentException
        // For this context, returning an empty list seems a reasonable fallback
        // rather than crashing if the Option object itself is invalid.
        return Collections.emptyList();
    }

    // 2. Get the actual values for the option from the command line
    List<Object> actualValues = (List<Object>) values.get(option);

    // 3. If no actual values are present, try the external default values provided as a parameter
    if (actualValues == null || actualValues.isEmpty()) {
        if (externalDefaultValues != null && !externalDefaultValues.isEmpty()) {
            actualValues = externalDefaultValues;
        }
    }

    // 4. If still no values (neither actual nor external default),
    //    then try the internal, pre-configured default values for this option.
    //    This assumes internal defaults are the last fallback.
    if (actualValues == null || actualValues.isEmpty()) {
        List<Object> internalDefaultValues = (List<Object>) this.defaultValues.get(option);
        if (internalDefaultValues != null && !internalDefaultValues.isEmpty()) {
            actualValues = internalDefaultValues;
        }
    }

    // 5. Ensure a non-null, unmodifiable list is always returned.
    //    If actualValues is still null or empty, return an empty list.
    //    Otherwise, return an unmodifiable copy to prevent external modification.
    if (actualValues == null || actualValues.isEmpty()) {
        return Collections.emptyList();
    } else {
        // Return an unmodifiable copy to protect internal state
        return Collections.unmodifiableList(new ArrayList<>(actualValues));
    }
}
