protected StringBuffer renderWrappedText(StringBuffer sb, int width,
                                             int nextLineTabStop, String text)
    {
        if (text == null)
        {
            return sb; // Or throw IllegalArgumentException, depending on desired behavior
        }
        if (width < 1) {
            // If width is too small, just append the text without wrapping
            sb.append(rtrim(text));
            return sb;
        }
        if (nextLineTabStop < 0) {
            nextLineTabStop = 0; // Sanitize negative tab stop
        }

        // Handle the first line
        int pos = findWrapPos(text, width, 0);

        if (pos == -1)
        {
            sb.append(rtrim(text));
            return sb;
        }
        sb.append(rtrim(text.substring(0, pos))).append(defaultNewLine);

        // All following lines must be padded with nextLineTabStop space characters
        final String padding = createPadding(nextLineTabStop);

        String remainingText = text.substring(pos).trim();

        while (!remainingText.isEmpty())
        {
            // Prepend padding for subsequent lines
            String lineToWrap = padding + remainingText;

            // Adjust width for findWrapPos to account for padding
            // The effective width for the content is width - nextLineTabStop
            // However, findWrapPos likely expects the total line width.
            // If findWrapPos calculates based on total width, then the width parameter is correct.
            // Assuming findWrapPos works with the total line width.
            pos = findWrapPos(lineToWrap, width, 0); // Start from 0 for the padded line

            if (pos == -1)
            {
                sb.append(rtrim(lineToWrap)); // Apply rtrim to the last segment
                return sb;
            }

            sb.append(rtrim(lineToWrap.substring(0, pos))).append(defaultNewLine);
            remainingText = lineToWrap.substring(pos).trim();
        }
        return sb;
    }
