package org.apache.commons.cli;

public class HelpFormatter {
    // ... existing fields ...
    public String defaultNewLine = System.getProperty("line.separator");

    // Placeholder for other helper methods
    protected int findWrapPos(String text, int width, int startPos) {
        // Dummy implementation for compilation. Real implementation would be in HelpFormatter.
        if (text == null || text.isEmpty() || width <= 0) {
            return -1;
        }
        if (text.length() <= width) {
            return -1; // No wrap needed
        }
        // Simple word wrap logic for demonstration: find last space before width
        int lastSpace = text.lastIndexOf(' ', width - 1);
        if (lastSpace != -1) {
            return lastSpace;
        }
        // If no space, just break at width
        return width;
    }

    protected String createPadding(int len) {
        if (len < 0) {
            return "";
        }
        char[] paddingChars = new char[len];
        java.util.Arrays.fill(paddingChars, ' ');
        return new String(paddingChars);
    }

    protected String rtrim(String s) {
        if (s == null) {
            return null;
        }
        int i = s.length() - 1;
        while (i >= 0 && Character.isWhitespace(s.charAt(i))) {
            i--;
        }
        return s.substring(0, i + 1);
    }

    /**
     * Renders the given text into the provided StringBuffer, wrapping lines to the specified width.
     * Subsequent lines after the first will be indented by `nextLineTabStop` spaces.
     *
     * @param sb The StringBuffer to append the wrapped text to. Must not be null.
     * @param width The maximum width of each line. Must be a positive integer.
     * @param nextLineTabStop The number of spaces to indent subsequent lines. Must be non-negative.
     * @param text The text to wrap. If null or empty, nothing will be appended.
     * @return The StringBuffer instance with the wrapped text appended.
     * @throws IllegalArgumentException if `sb` is null, `width` is not positive, or `nextLineTabStop` is negative.
     */
    protected StringBuffer renderWrappedText(StringBuffer sb, int width,
                                             int nextLineTabStop, String text) {
        // Robustness: Input validation
        if (sb == null) {
            throw new IllegalArgumentException("StringBuffer cannot be null.");
        }
        if (width <= 0) {
            throw new IllegalArgumentException("Width must be positive.");
        }
        if (nextLineTabStop < 0) {
            throw new IllegalArgumentException("Next line tab stop cannot be negative.");
        }
        if (text == null || text.isEmpty()) {
            return sb; // Nothing to wrap or append
        }

        int currentPos = 0;
        // First line processing: no padding
        int wrapPos = findWrapPos(text, width, currentPos);

        if (wrapPos == -1) {
            // Text fits on one line
            sb.append(rtrim(text));
            return sb;
        }

        // Append the first line segment
        sb.append(rtrim(text.substring(0, wrapPos))).append(defaultNewLine);

        // Prepare padding for subsequent lines
        final String padding = createPadding(nextLineTabStop);

        // Process subsequent lines
        String remainingText = text.substring(wrapPos).trim(); // Trim leading spaces from wrapped part

        while (true) {
            if (remainingText.isEmpty()) {
                break; // No more text to process
            }

            // Prepend padding for the new line
            String lineToWrap = padding + remainingText;

            // Find wrap position for the padded line.
            // The effective width for content is width - nextLineTabStop.
            // findWrapPos needs to consider the total line length, including padding.
            wrapPos = findWrapPos(lineToWrap, width, 0); // Start searching from beginning of lineToWrap

            if (wrapPos == -1) {
                // The remaining text (with padding) fits on one line
                sb.append(lineToWrap);
                break; // All text processed
            }

            // Append the wrapped segment of the current line
            sb.append(rtrim(lineToWrap.substring(0, wrapPos))).append(defaultNewLine);

            // Update remaining text for the next iteration
            remainingText = lineToWrap.substring(wrapPos).trim();
        }

        return sb;
    }
}
