package org.apache.commons.cli; // Assuming the original package

import java.util.Objects; // For Objects.requireNonNull

public class OptionBuilder {

    // Use ThreadLocal to make the static fields thread-safe
    private static final ThreadLocal<String> TL_LONGOPT = ThreadLocal.withInitial(() -> null);
    private static final ThreadLocal<String> TL_DESCRIPTION = ThreadLocal.withInitial(() -> null);
    private static final ThreadLocal<String> TL_ARG_NAME = ThreadLocal.withInitial(() -> null);
    private static final ThreadLocal<Boolean> TL_REQUIRED = ThreadLocal.withInitial(() -> false);
    private static final ThreadLocal<Integer> TL_NUMBER_OF_ARGS = ThreadLocal.withInitial(() -> Option.UNINITIALIZED);
    private static final ThreadLocal<Object> TL_TYPE = ThreadLocal.withInitial(() -> null); // Defaults to String
    private static final ThreadLocal<Boolean> TL_OPTIONAL_ARG = ThreadLocal.withInitial(() -> false);
    private static final ThreadLocal<Character> TL_VALUE_SEP = ThreadLocal.withInitial(() -> (char) 0); // Default to NUL char

    // Constructor remains private as it's a utility class
    private OptionBuilder() {
    }

    /**
     * Resets the ThreadLocal properties of the OptionBuilder for the current thread.
     * This ensures that subsequent option creations in the same thread start with a clean state.
     */
    private static void reset() {
        TL_LONGOPT.remove();
        TL_DESCRIPTION.remove();
        TL_ARG_NAME.remove();
        TL_REQUIRED.set(false);
        TL_NUMBER_OF_ARGS.set(Option.UNINITIALIZED);
        TL_TYPE.remove();
        TL_OPTIONAL_ARG.set(false);
        TL_VALUE_SEP.set((char) 0);
    }

    // Existing fluent methods would be updated to use ThreadLocal fields.
    // Example for one fluent method:
    public static OptionBuilder withLongOpt(String newLongopt) {
        TL_LONGOPT.set(newLongopt);
        return instance; // instance is still static, but it's just a reference to the builder itself
    }

    // ... (other fluent methods would similarly be updated to use ThreadLocal) ...
    public static OptionBuilder withDescription(String newDescription) {
        TL_DESCRIPTION.set(newDescription);
        return instance;
    }

    public static OptionBuilder isRequired() {
        TL_REQUIRED.set(true);
        return instance;
    }

    public static OptionBuilder hasArgs() {
        TL_NUMBER_OF_ARGS.set(Option.UNLIMITED_VALUES);
        return instance;
    }

    public static OptionBuilder hasArgs(int num) {
        if (num < 0 && num != Option.UNLIMITED_VALUES) {
            throw new IllegalArgumentException("numberOfArgs must be zero or positive, or Option.UNLIMITED_VALUES");
        }
        TL_NUMBER_OF_ARGS.set(num);
        return instance;
    }

    public static OptionBuilder hasArg() {
        TL_NUMBER_OF_ARGS.set(1); // Default to one argument if hasArg() is called without a specific number
        return instance;
    }

    public static OptionBuilder hasArg(boolean hasArg) {
        TL_NUMBER_OF_ARGS.set(hasArg ? 1 : 0);
        return instance;
    }

    public static OptionBuilder hasOptionalArg() {
        TL_OPTIONAL_ARG.set(true);
        TL_NUMBER_OF_ARGS.set(1); // An optional arg implies at least one arg
        return instance;
    }

    public static OptionBuilder hasOptionalArgs() {
        TL_OPTIONAL_ARG.set(true);
        TL_NUMBER_OF_ARGS.set(Option.UNLIMITED_VALUES); // Optional unlimited args
        return instance;
    }

    public static OptionBuilder withArgName(String name) {
        TL_ARG_NAME.set(name);
        return instance;
    }

    public static OptionBuilder withType(Object newType) {
        TL_TYPE.set(newType);
        return instance;
    }

    public static OptionBuilder withValueSeparator(char sep) {
        TL_VALUE_SEP.set(sep);
        return instance;
    }

    public static OptionBuilder withValueSeparator() {
        TL_VALUE_SEP.set(Option.DEFAULT_VALUE_SEPARATOR); // Assuming Option defines a default
        return instance;
    }

    private static OptionBuilder instance = new OptionBuilder(); // Remains for fluent API calls like OptionBuilder.hasArg().create()

    /**
