     *                                  combination of properties is set.
     */
    public static Option create(String opt) throws IllegalArgumentException {
        // Input validation for 'opt'
        Objects.requireNonNull(opt, "Short option name 'opt' cannot be null.");
        if (opt.isEmpty()) {
            throw new IllegalArgumentException("Short option name 'opt' cannot be empty.");
        }

        // Retrieve properties from ThreadLocal fields
        String longopt = TL_LONGOPT.get();
        String description = TL_DESCRIPTION.get();
        boolean required = TL_REQUIRED.get();
        int numberOfArgs = TL_NUMBER_OF_ARGS.get();
        Object type = TL_TYPE.get();
        boolean optionalArg = TL_OPTIONAL_ARG.get();
        char valuesep = TL_VALUE_SEP.get();
        String argName = TL_ARG_NAME.get();

        // Determine hasArg based on numberOfArgs
        // The Option constructor can derive hasArg from numberOfArgs, but explicitly passing it
        // might be clearer if a constructor taking it directly were used.
        // For the chosen constructor Option(String opt, String description), we rely on setters.

        // create the option - using the constructor that takes short opt and description
