public boolean isDoubleMetaphoneEqual(final String value1, final String value2, final boolean alternate) {
    // Handle null inputs explicitly to prevent NullPointerExceptions and ensure clear behavior.
    // If both are null, they are considered equal.
    if (value1 == null && value2 == null) {
        return true;
    }
    // If one is null and the other is not, they are not equal.
    if (value1 == null || value2 == null) {
        return false;
    }

    // Generate the Double Metaphone codes for both strings using the specified alternate flag.
    final String metaphone1 = doubleMetaphone(value1, alternate);
    final String metaphone2 = doubleMetaphone(value2, alternate);

    // It's possible that the doubleMetaphone method itself returns null for certain inputs
    // even after initial null checks. This additional check makes the comparison robust.
    // If both metaphone codes are null, they are considered equal (unlikely given
    // previous null checks and expected behavior of doubleMetaphone to return String).
    if (metaphone1 == null && metaphone2 == null) {
        return true;
    }
    // If one metaphone code is null and the other is not, they are not equal.
    if (metaphone1 == null || metaphone2 == null) {
        return false;
    }

    // Compare the generated Double Metaphone codes for equality.
    return metaphone1.equals(metaphone2);
}
