    JsonToken token = peek();
    switch (token) {
      case NAME:
        // Consume the name, then skip its associated value.
        // nextName() advances the internal state to the value itself.
        nextName();
        // Now, the reader is positioned at the value. We recursively call skipValue
        // to handle the actual value, which could be a primitive, object, or array.
