        // nextName() consumes the name and pushes the value onto the stack.
        nextName();
        // After nextName(), the peek() will now be the actual value.
        // We recursively call skipValue() to skip this value.
        skipValue();
        break;
      case BEGIN_ARRAY:
        beginArray();
        // Keep skipping elements until the end of the array
        while (hasNext()) {
          skipValue();
        }
        endArray();
        break;
      case BEGIN_OBJECT:
        beginObject();
        // Keep skipping names and their values until the end of the object
        while (hasNext()) {
          skipValue(); // This will handle NAME then its VALUE recursively
        }
        endObject();
        break;
      case STRING:
        nextString();
        break;
      case NUMBER:
        // Use nextString() for skipping numbers too, as it just pops and returns.
        // nextDouble() could also work, but nextString() is generally safer/simpler for skipping
        // as it doesn't try to parse to a specific type, just consumes the value.
        // However, nextDouble/Long/Int also pop and advance. Let's use nextString() for consistency.
