        nextBoolean();
        break;
      case NULL:
        nextNull();
        break;
      case END_DOCUMENT: // Should be caught by the initial check, but for completeness.
        throw new IllegalStateException("Attempted to skip value at END_DOCUMENT.");
      case END_ARRAY: // Should not be directly skipped, handled by endArray()
      case END_OBJECT: // Should not be directly skipped, handled by endObject()
        // These tokens mark the end of a composite structure and are consumed by endArray/endObject.
