      final int constructorId = (Integer) getConstructorIdMethod.invoke(null, Object.class);

      final Method newInstanceMethod = ObjectStreamClass.class
          .getDeclaredMethod("newInstance", Class.class, int.class);
      newInstanceMethod.setAccessible(true);

      logger.log(Level.FINE, "Using ObjectStreamClass for object allocation (post-Gingerbread Dalvik).");
      return new UnsafeAllocator() {
        @Override
        @SuppressWarnings("unchecked")
        public <T> T newInstance(Class<T> c) throws Exception {
