            throw new IllegalArgumentException("Class cannot be null for newInstance.");
          }
          return (T) newInstanceMethod.invoke(null, c, constructorId);
        }
      };
    } catch (Throwable e) {
      logger.log(Level.FINER, "Failed to use ObjectStreamClass for object allocation.", e);
    }

    // Attempt 3: Dalvik VM, pre-Gingerbread (ObjectInputStream.newInstance)
    try {
