        if (start == 0 && end == 0) {
            if (chars != null) {
                end = chars.length;
            } else {
                if (!letters && !numbers) {
                    // Default to full Unicode BMP range for clarity and to avoid Integer.MAX_VALUE issues
                    start = Character.MIN_VALUE; // 0
                    end = Character.MAX_VALUE + 1; // 65536
                } else {
                    // Default to common alphanumeric range (space to z)
                    start = ' ';
                    end = 'z' + 1;
                }
