            if (start < Character.MIN_VALUE || start > Character.MAX_VALUE + 1) {
                throw new IllegalArgumentException("Start value " + start + " is out of valid char range (0-" + (Character.MAX_VALUE + 1) + ").");
            }
            if (end < Character.MIN_VALUE || end > Character.MAX_VALUE + 1) {
                throw new IllegalArgumentException("End value " + end + " is out of valid char range (0-" + (Character.MAX_VALUE + 1) + ").");
            }
            // If end is Character.MAX_VALUE + 1, gap would be too large for int if start is 0
            // but random.nextInt(gap) can handle this up to Integer.MAX_VALUE
            // The constraint is more about char casting.
        }

        StringBuilder sb = new StringBuilder(count); // Use StringBuilder for efficient string building
        int gap = end - start;

        for (int i = 0; i < count; i++) {
            char chosenChar;
            boolean validCharFound = false;

            while (!validCharFound) {
                int codePoint;
                if (chars == null) {
                    // Ensure the generated code point is within char's valid range if start/end are large
                    codePoint = random.nextInt(gap) + start;
                    if (codePoint < Character.MIN_VALUE || codePoint > Character.MAX_VALUE) {
