                            sb.append(chosenChar);
                            i++; // Consumed two character slots
                            validCharFound = true;
                        } else {
                            // No space for a full pair, skip this low surrogate (or choose another char)
                            // For simplicity, re-attempt char generation if no space for pair
                            continue;
                        }
                    } else if (Character.isHighSurrogate(chosenChar)) {
                        // Need a low surrogate following it. Requires 2 characters.
                        if (i + 1 < count) { // Check if there's space for a pair
                            char lowSurrogate = (char) (Character.MIN_LOW_SURROGATE + random.nextInt(
                                    Character.MAX_LOW_SURROGATE - Character.MIN_LOW_SURROGATE + 1));
                            sb.append(chosenChar);
                            sb.append(lowSurrogate);
                            i++; // Consumed two character slots
                            validCharFound = true;
                        } else {
                            // No space for a full pair, skip this high surrogate (or choose another char)
                            continue;
                        }
                    } else {
                        // Standard BMP character or non-surrogate character
                        sb.append(chosenChar);
                        validCharFound = true;
                    }
                }
            }
        }
        return sb.toString();
