import java.util.concurrent.ThreadLocalRandom; // A better default Random source

public class RandomStringUtils {

    // Using ThreadLocalRandom for the static instance, as it's generally preferred
    // over a shared Random instance for multithreaded environments.
    private static final Random STATIC_RANDOM = ThreadLocalRandom.current();

    /**
     * Generates a random string of a specified length, composed of characters within a given range
     * or from a provided character array. Supports filtering for letters and numbers.
     * This method correctly handles surrogate pairs and ensures robust input validation.
     *
     * @param count     the length of the random string to generate. Must be non-negative.
     * @param start     the inclusive start character code point for the character range.
     *                  Only used if `chars` is null.
     * @param end       the exclusive end character code point for the character range.
     *                  Only used if `chars` is null.
     * @param letters   if true, only letter characters will be included in the generated string.
     * @param numbers   if true, only digit characters will be included in the generated string.
     *                  If both `letters` and `numbers` are false, any character within the
     *                  specified range (or from `chars`) will be used.
     * @param chars     an optional array of characters to choose from. If provided, `start`
     *                  and `end` are interpreted as indices into this array. If null, characters
     *                  are generated from the `start` to `end` code point range.
     * @param random    the {@link Random} instance to use for generating random numbers.
     *                  If null, a default {@link ThreadLocalRandom} instance will be used.
     * @return a random string.
     * @throws IllegalArgumentException if `count` is negative, if `chars` is an empty array,
     *                                  if `end` is less than or equal to `start` when `chars` is null,
     *                                  or if no valid characters can be chosen from the specified range/array.
     */
    public static String random(int count, int start, int end, boolean letters, boolean numbers,
                                char[] chars, Random random) {
        if (count < 0) {
            throw new IllegalArgumentException("Requested random string length " + count + " is less than 0.");
        }
        if (count == 0) {
            return "";
        }

        if (chars != null && chars.length == 0) {
            throw new IllegalArgumentException("The chars array must not be empty.");
        }

        final Random actualRandom = (random != null) ? random : STATIC_RANDOM;

        // Default character range logic
        if (start == 0 && end == 0) {
            if (chars != null) {
                // When chars are provided, start and end are indices into that array.
                // If they are 0, then we use the full length of the chars array.
                end = chars.length;
            } else {
                if (!letters && !numbers) {
                    // If no specific type is requested, and no chars array,
                    // use a common printable ASCII range to avoid non-printable characters.
                    // This is a more reasonable default than Integer.MAX_VALUE.
                    start = 32; // Space
                    end = 127;  // Del (exclusive)
                } else {
                    // Default to a wider range for letters and numbers if no specific chars array
                    // or start/end range is provided.
                    // Covers common ASCII letters, numbers, and symbols.
                    start = 32; // Space
                    end = 127; // Del (exclusive)
                }
            }
        }

        int gap;
        if (chars == null) {
            gap = end - start;
            if (gap <= 0) {
                throw new IllegalArgumentException("The 'end' parameter must be greater than 'start' when 'chars' is null.");
            }
        } else {
            gap = end - start;
            if (start < 0 || end > chars.length || gap <= 0) {
                 throw new IllegalArgumentException("Invalid 'start' or 'end' index for the 'chars' array. " +
                                                    "start=" + start + ", end=" + end + ", chars.length=" + chars.length);
            }
        }

        char[] buffer = new char[count];
        int bufferIndex = 0; // Use a separate index for the buffer

        while (bufferIndex < count) {
            char ch;
            if (chars == null) {
                ch = (char) (actualRandom.nextInt(gap) + start);
            } else {
                ch = chars[actualRandom.nextInt(gap) + start];
            }

            // Apply filtering for letters/numbers
            boolean isValidChar = false;
            if (letters && Character.isLetter(ch)) {
                isValidChar = true;
            } else if (numbers && Character.isDigit(ch)) {
                isValidChar = true;
            } else if (!letters && !numbers) {
                isValidChar = true; // No specific type requested, so any char is valid
            }

            if (isValidChar) {
                // Surrogate pair handling
                if (Character.isHighSurrogate(ch)) {
                    // High surrogate: needs a low surrogate to follow
                    if (bufferIndex + 1 < count) { // Ensure space for two characters
                        buffer[bufferIndex++] = ch;
                        buffer[bufferIndex++] = (char) (0xDC00 + actualRandom.nextInt(0x400)); // Random low surrogate (DCOO-DFFF)
                    } else {
                        // Not enough space for a full surrogate pair, re-try this position
                        // (or potentially choose a non-surrogate char)
                        continue; // Skip current iteration, don't increment bufferIndex
                    }
                } else if (Character.isLowSurrogate(ch)) {
                    // Low surrogate: needs a high surrogate to precede it
                    // This scenario is less common when picking random chars, as typically
                    // you'd pick a codepoint and then convert. However, if 'chars' array
                    // contained a lone low surrogate, we need to handle it.
                    if (bufferIndex + 1 < count) { // Ensure space for two characters
                        buffer[bufferIndex++] = (char) (0xD800 + actualRandom.nextInt(0x400)); // Random high surrogate (D800-DBFF)
                        buffer[bufferIndex++] = ch;
                    } else {
                        continue; // Skip current iteration, don't increment bufferIndex
                    }
                } else {
                    // Not a surrogate or a valid non-surrogate character
                    buffer[bufferIndex++] = ch;
                }
            }
            // If isValidChar is false, loop continues without incrementing bufferIndex, effectively retrying.
        }
        return new String(buffer);
    }
}
