                    // If a low surrogate is generated without a preceding high surrogate, it's invalid.
                    // Option 1: Skip it.
                    // Option 2: Try to prepend a high surrogate (which requires looking back, complex).
                    // For simplicity and correctness, if a low surrogate is randomly generated standalone, skip it.
                    // This implies the intended character set (if custom) or range should ideally avoid standalone surrogates.
                    continue; // Skip standalone low surrogates
                } else if (Character.isSurrogate(ch)) { // Covers private use surrogates (U+DB80 to U+DBFF)
                    // If these are not intended, skip them.
                    continue;
                } else {
                    // Regular character, append it
                    buffer.append(ch);
                    charsNeeded--;
                }
            }
            // If character doesn't match filters, loop continues and tries a new character for the same position.
        }
        return buffer.toString();
    }
}
