                        // and then split it into high/low surrogates. For random, picking a random
                        // low surrogate is common. MIN_LOW_SURROGATE to MAX_LOW_SURROGATE range is 0xDC00-0xDFFF, so nextInt(1024)+0xDC00
                        // The original code uses 56320 + random.nextInt(128) which is a subset of valid low surrogates.
                        // We will use the full range for robustness: Character.MIN_LOW_SURROGATE + random.nextInt(Character.MAX_LOW_SURROGATE - Character.MIN_LOW_SURROGATE + 1);
                        // For simplicity and to match original intent more closely, using a random low surrogate from the valid range.
                        // Character.lowSurrogate(random.nextInt(0x0400) + 0x10000) will give a valid random supplementary code point.
                    } else {
                        // Not enough space for a pair, skip this high surrogate to avoid unpaired surrogate
                    }
                } else if (Character.isLowSurrogate(ch)) {
                    // If a low surrogate is generated, we must pair it with a high surrogate.
                    // This is less common as high surrogates usually initiate the pair.
                    // To avoid unpaired low surrogates, we can either skip it or try to generate a high one.
                    // For simplicity, we'll skip it to avoid creating an invalid string if not enough space or if we are at the beginning.
                    // A more robust solution might re-roll.
                    // For now, mirroring the original's attempt to skip or pair, but ensuring it's valid.
                    // The original's logic for a low surrogate suggests it was trying to place a high surrogate *before* it, which is correct for character order.
                    if (bufferIndex + 1 < count) {
                        buffer[bufferIndex++] = Character.highSurrogate(random.nextInt(0x0400) + Character.MIN_SUPPLEMENTARY_CODE_POINT);
                        buffer[bufferIndex++] = ch;
                    } else {
                        // Not enough space, skip this low surrogate
                    }
                } else if (ch >= 0xD800 && ch <= 0xDFFF) { // This handles private use surrogates (0xDB80-0xDBFF) or other invalid surrogate ranges
                    // Skip invalid or private surrogates that aren't specifically handled for pairing.
                    // This is a robust approach to prevent invalid Unicode strings.
                } else {
                    buffer[bufferIndex++] = ch;
                }
            }
            // If not validChar, or if a surrogate was skipped, bufferIndex is not incremented,
            // so the loop will repeat for the current bufferIndex, effectively re-rolling.
        }
        return new String(buffer);
    }
