import java.util.Random;

public class RandomStringUtils {

    // (Assuming other fields and methods from the original context are present)

    /**
     * <p>Generates a random string of a specified length from the supplied
     * character set, optionally filtered by letters and numbers.
     * This method supports generating full Unicode code points, including
     * supplementary characters, and handles surrogate pairs correctly.</p>
     *
     * <p>The character generation depends on the parameters:
     * <ul>
     *     <li>If {@code chars} is provided (not null and not empty), characters are picked from it.
     *         In this case, {@code start} and {@code end} are ignored.</li>
     *     <li>If {@code chars} is null or empty, characters are generated from the Unicode range
     *         specified by {@code start} (inclusive) and {@code end} (exclusive).
     *         If {@code start == 0} and {@code end == 0}, a default range is used:
     *         <ul>
     *             <li>If {@code !letters && !numbers}, the range is U+0000 to U+10FFFF (all Unicode).</li>
     *             <li>Otherwise, the range is ASCII from ' ' (U+0020) to 'z' (U+007A).</li>
     *         </ul>
     *     </li>
     * </ul>
     * </p>
     *
     * <p>The {@code letters} and {@code numbers} flags further filter the generated characters:
     * <ul>
     *     <li>If {@code letters} is true, only Unicode letters are accepted.</li>
     *     <li>If {@code numbers} is true, only Unicode digits are accepted.</li>
     *     <li>If both {@code letters} and {@code numbers} are true, both letters and digits are accepted.</li>
     *     <li>If both {@code letters} and {@code numbers} are false, all characters from the chosen
     *         character source ({@code chars} or {@code start}/{@code end} range) are accepted
     *         (provided they are not invalid surrogate code points that cannot form a pair).</li>
     * </ul>
     * </p>
     *
     * @param count     the length of the random string to create. Must be non-negative.
     * @param start     the first code point (inclusive) in the character range, or ignored if {@code chars} is provided.
     *                  Must be {@code <= end}.
     * @param end       the last code point (exclusive) in the character range, or ignored if {@code chars} is provided.
     *                  Must be {@code >= start}.
     * @param letters   if {@code true}, generated characters must be a letter.
     * @param numbers   if {@code true}, generated characters must be a number.
     * @param chars     a character array to draw random characters from. If null or empty,
     *                  characters are drawn from the code point range defined by {@code start} and {@code end}.
     * @param random    the source of randomness. Must not be null.
     * @return a random string.
     * @throws IllegalArgumentException if {@code count} is negative, {@code start > end},
     *                                  {@code chars} is empty, {@code random} is null,
     *                                  or if it's impossible to generate a string matching criteria.
     */
    public static String random(int count, int start, int end, boolean letters, boolean numbers,
                                char[] chars, Random random) {
        if (count < 0) {
            throw new IllegalArgumentException("Requested random string length " + count + " is less than 0.");
        }
        if (count == 0) {
            return "";
        }
        if (random == null) {
            throw new IllegalArgumentException("Random generator cannot be null.");
        }

        // Determine character source and range
        final int codePointStart;
        final int codePointEnd;
        final char[] charSource;

        if (chars != null && chars.length > 0) {
            charSource = chars;
            codePointStart = 0; // Use as index start
            codePointEnd = chars.length; // Use as index end
        } else {
            charSource = null;
            if (start == 0 && end == 0) {
                if (!letters && !numbers) {
                    codePointStart = Character.MIN_CODE_POINT; // Full Unicode
                    codePointEnd = Character.MAX_CODE_POINT + 1;
                } else {
                    codePointStart = ' '; // ASCII space
                    codePointEnd = 'z' + 1; // ASCII 'z'
                }
            } else {
                codePointStart = start;
                codePointEnd = end;
            }

            if (codePointStart < 0 || codePointEnd < 0 || codePointStart > codePointEnd) {
                throw new IllegalArgumentException("Invalid code point range: start=" + codePointStart + ", end=" + codePointEnd);
            }
            if (codePointEnd - codePointStart == 0) {
                 throw new IllegalArgumentException("Code point range is empty: start=" + codePointStart + ", end=" + codePointEnd);
            }
        }

        StringBuilder sb = new StringBuilder(count);
        int currentCount = 0;
        int retries = 0; // To prevent infinite loops

        while (currentCount < count) {
            int codePoint;

            if (charSource != null) {
                // Pick from provided char array (start and end are treated as indices)
                int index = random.nextInt(codePointEnd - codePointStart) + codePointStart;
                codePoint = charSource[index]; // Note: This might be a char, not a full code point
                                               // If charSource contains high/low surrogates separated,
                                               // this needs more complex handling to ensure pairs.
                                               // For simplicity, we treat charSource as individual chars.
            } else {
                // Generate from code point range
                codePoint = random.nextInt(codePointEnd - codePointStart) + codePointStart;
            }

            // Filter by letters/numbers
            boolean isLetter = Character.isLetter(codePoint);
            boolean isDigit = Character.isDigit(codePoint);

            if ((letters && !isLetter) || (numbers && !isDigit) ||
                (!letters && !numbers && Character.isSurrogate((char)codePoint)) // If no filter, don't allow single surrogates
            ) {
                // If filtering is active and char doesn't match, or it's a single surrogate when not filtered,
                // try again.
                retries++;
                if (retries > 1000) { // Safety break for potential infinite loops
                    throw new IllegalArgumentException("Could not generate a character matching criteria after 1000 retries. " +
                            "Check 'start', 'end', 'letters', 'numbers', and 'chars' parameters.");
                }
                continue; // Try generating another character
            }

            // Handle code points that require surrogate pairs
            if (Character.isSupplementaryCodePoint(codePoint)) {
                // A supplementary code point needs two chars.
                // Check if there's enough space in the remaining count.
                if (currentCount + 2 > count) {
                    // Not enough space for a full supplementary character.
                    // Retry with a non-supplementary character if possible, or throw error.
                    retries++;
                    if (retries > 1000) {
                        throw new IllegalArgumentException("Cannot fit supplementary character. Remaining count " + (count - currentCount));
                    }
                    continue;
                }
                char[] charsPair = Character.toChars(codePoint);
                sb.append(charsPair[0]).append(charsPair[1]);
                currentCount += 2;
            } else if (Character.isHighSurrogate((char) codePoint) || Character.isLowSurrogate((char) codePoint)) {
                 // Disallow isolated surrogates if not explicitly handled to form pairs.
                 // This situation primarily happens if 'charSource' contains isolated surrogates,
                 // or the start/end range picks only a single surrogate.
                 retries++;
                 if (retries > 1000) {
                     throw new IllegalArgumentException("Isolated surrogate generated. Cannot form valid string.");
                 }
                 continue;
            }
            else {
                // Regular character
                sb.append((char) codePoint);
                currentCount++;
            }
            retries = 0; // Reset retries after successful character addition
        }

        return sb.toString();
    }
}
