public static boolean equals(CharSequence cs1, CharSequence cs2) {
    if (cs1 == cs2) {
        return true;
    }
    if (cs1 == null || cs2 == null) {
        return false;
    }
    // If one is String and the other is not, String's equals(Object) will return false.
    // If both are Strings, String.equals(String) works.
    // To ensure content comparison for all CharSequence types,
    // we convert them to String and then compare.
    // This is a common approach in utility libraries for CharSequence comparison.
    // Alternatively, one could iterate through characters if String conversion
    // is deemed too heavy for very large sequences or specific scenarios,
    // but for general utility, String conversion is often simpler and robust.
    return cs1.toString().equals(cs2.toString());
}
