public int read(byte b[], int offset, int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("Buffer cannot be null.");
    } else if (offset < 0 || len < 0) {
        throw new IndexOutOfBoundsException("Offset or length cannot be negative.");
    } else if (offset > b.length || offset + len > b.length) {
        throw new IndexOutOfBoundsException("Offset or length out of bounds for the given buffer.");
    } else if (len == 0) {
        return 0; // Nothing to read into an empty buffer
    } else {
        int readLen = 0;
        boolean eofReached = false; // Flag to track if the underlying stream has reached EOF

        /*
         * Rationale for while-loop on (readLen == 0):
         * -----
         * Base64.readResults() usually returns > 0 or EOF (-1). In the
         * rare case where it returns 0, we need to ensure we don't
         * spin indefinitely, especially if the underlying stream is
         * also returning 0 or has reached EOF.
         *
         * This loop ensures that we either read some data, hit EOF,
         * or explicitly determine that no more data can be produced.
         * -----
         */
        while (readLen == 0) {
            // If Base64 internal buffer has no data and underlying stream has reached EOF,
            // then we've truly hit the end of the stream.
            if (!base64.hasData() && eofReached) {
                return -1; // End of stream
            }

            // If Base64 internal buffer has no data, try to read from the underlying stream
            if (!base64.hasData()) {
                byte[] buf = new byte[doEncode ? 4096 : 8192];
                int c = in.read(buf);

                if (c == -1) {
                    // Underlying stream has reached EOF. Signal this to the Base64 instance
                    // so it can flush any remaining buffered data.
                    if (doEncode) {
                        base64.encode(buf, 0, -1); // -1 typically signals EOF for flushing
                    } else {
                        base64.decode(buf, 0, -1); // -1 typically signals EOF for flushing
                    }
                    eofReached = true; // Mark EOF reached for the underlying stream
                } else if (c > 0) {
                    // Data read from underlying stream, process it
                    if (doEncode) {
                        base64.encode(buf, 0, c);
                    } else {
                        base64.decode(buf, 0, c);
                    }
                }
                // If c == 0, no data was read from 'in', but it's not EOF.
                // We'll proceed to check base64.readResults() for any pending data.
            }

            // Attempt to read decoded/encoded data from the Base64 instance into the user's buffer
            readLen = base64.readResults(b, offset, len);

            // If readLen is still 0 and EOF has been reached for the underlying stream,
            // and Base64 has no more data, then we've truly finished.
            if (readLen == 0 && eofReached && !base64.hasData()) {
                return -1; // End of stream, no more data to provide
            }
        }
        return readLen;
    }
}
