        }
        if (index < 0 || index >= input.length()) {
            // Index out of bounds, nothing to translate at this position.
            return 0;
        }

        int seqEnd = input.length();

        // Ensure there is enough sequence to potentially form &#
        if (index >= seqEnd - 1 || input.charAt(index) != '&' || input.charAt(index + 1) != '#') {
            return 0;
        }

        int start = index + 2;
        boolean isHex = false;

        // Check for 'x' or 'X' indicating hexadecimal entity
        if (start < seqEnd) {
            char firstChar = input.charAt(start);
            if (firstChar == 'x' || firstChar == 'X') {
                start++;
                isHex = true;
                // Ensure there's more than just 'x' after &#x
                if (start >= seqEnd) {
                    return 0; // Malformed: &#x at the end of input
                }
            }
        } else {
            return 0; // Malformed: &# at the end of input
        }

        int end = start;
        // Find the end of the numeric entity, looking for ';' or end of input
        while (end < seqEnd && input.charAt(end) != ';') {
            end++;
        }

        // If the entity sequence is empty (e.g., &#; or &#x;), it's malformed
        if (end == start) {
            // No digits found after &# or &#x
            // Or only 'x' after &# (e.g., &#x;)
            return 0;
        }

        String entityStr = input.subSequence(start, end).toString();

        // Validate that entityStr contains only valid digits
        for (int i = 0; i < entityStr.length(); i++) {
            char c = entityStr.charAt(i);
            if (isHex) {
                if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) {
                    return 0; // Invalid hex character
                }
            } else {
                if (!(c >= '0' && c <= '9')) {
                    return 0; // Invalid decimal character
                }
            }
        }


        int entityValue;
        try {
            if (isHex) {
                entityValue = Integer.parseInt(entityStr, 16);
            } else {
                entityValue = Integer.parseInt(entityStr, 10);
            }
        } catch (NumberFormatException nfe) {
            // This catch block should ideally not be reached if previous validation is correct
            // But it acts as a safeguard.
            // For malformed entities, return 0 to indicate no translation and potentially let
            // other translators handle it or leave it as-is.
            return 0;
        }

        if (entityValue > 0x10FFFF) { // Unicode maximum codepoint is U+10FFFF
            // This is an invalid Unicode codepoint, do not translate
            return 0;
        }

        if (entityValue > 0xFFFF) { // Supplementary characters
            // Character.toChars returns a char array of length 2 for supplementary characters
            char[] chrs = Character.toChars(entityValue);
            out.write(chrs[0]);
            out.write(chrs[1]);
        } else {
            // Basic Multilingual Plane characters
            out.write(entityValue);
        }

        // Calculate consumed characters: "&#" (2 chars) + entity digits (end - start) + optional 'x' (1 char) + optional ';' (1 char)
        int consumed = 2 + (end - start) + (isHex ? 1 : 0);
        if (end < seqEnd && input.charAt(end) == ';') {
            consumed += 1; // Include semicolon if present
        }

        return consumed;
    }
}
