                    // Not a valid decimal digit, consider the entity ended here (without semicolon)
                    break;
                }
            }
            entityValueEnd++;
        }

        // If no digits were found after &# or &#x
        if (entityValueEnd == currentParseIndex) {
            return 0; // No numeric part found (e.g., &#; &#x;)
        }

        int entityValue;
        try {
            String entityStr = input.subSequence(currentParseIndex, entityValueEnd).toString();
            if (isHex) {
                entityValue = Integer.parseInt(entityStr, 16);
            } else {
                entityValue = Integer.parseInt(entityStr, 10);
            }
