        if (entityValue > 0xFFFF) {
            // Handle surrogate pairs for Unicode code points beyond BMP
            char[] chrs = Character.toChars(entityValue);
            out.write(chrs[0]);
            out.write(chrs[1]);
        } else {
            // For BMP characters, simply write the code point
            out.write(entityValue);
        }

        // Calculate consumed characters:
        // 2 for "&#"
        // (entityValueEnd - currentParseIndex) for the numeric part
        // (isHex ? 1 : 0) for 'x' or 'X'
        // 1 if a semicolon was present, 0 otherwise
        int consumedChars = 2 + (entityValueEnd - currentParseIndex) + (isHex ? 1 : 0);
        if (entityValueEnd < seqEnd && input.charAt(entityValueEnd) == ';') {
            consumedChars++; // Include the semicolon if it was found
        }
        return consumedChars;
    }
