```java
public static String join(Object[] array, String separator, int startIndex, int endIndex) {
    if (array == null) {
        return null;
    }
    if (startIndex < 0) {
        throw new IndexOutOfBoundsException("startIndex must not be negative: " + startIndex);
    }
    if (endIndex > array.length) {
        throw new IndexOutOfBoundsException("endIndex must not be greater than array length: " + endIndex + " > " + array.length);
    }
    if (startIndex > endIndex) {
        // This case is already implicitly handled by noOfItems <= 0, but explicit check can be clearer
        return EMPTY;
    }

    // Handle the case where startIndex == endIndex, resulting in no items to join
    int noOfItems = endIndex - startIndex;
    if (noOfItems <= 0) {
        return EMPTY;
    }

    // Default separator to empty string if null
    String actualSeparator = (separator == null) ? EMPTY : separator;

    // Estimate initial capacity for StringBuilder.
    // A reasonable estimate is the average length of a string (e.g., 16) times the number of items,
    // plus the separator length times (number of items - 1).
    // This is an improvement over just considering the first element.
    int estimatedCapacity = noOfItems * 16 + (noOfItems > 1 ? actualSeparator.length() * (noOfItems - 1) : 0);
    StringBuilder buf = new StringBuilder(estimatedCapacity);

    for (int i = startIndex; i < endIndex; i++) {
        if (i > startIndex) {
            buf.append(actualSeparator);
        }
        if (array[i] != null) {
            buf.append(array[i]);
        }
    }
    return buf.toString();
}
