```java
public static String join(Object[] array, String separator, int startIndex, int endIndex) {
    if (array == null) {
        return null;
    }
    if (separator == null) {
        separator = EMPTY;
    }

    // Validate indices to prevent ArrayIndexOutOfBoundsException
    if (startIndex < 0) {
        startIndex = 0; // Or throw IllegalArgumentException
    }
    if (endIndex > array.length) {
        endIndex = array.length; // Or throw IllegalArgumentException
    }

    int noOfItems = (endIndex - startIndex);
    if (noOfItems <= 0) {
        return EMPTY;
    }

    // Estimate initial capacity more accurately to reduce reallocations.
    // Sum estimated lengths of all elements and separators.
    int estimatedLength = 0;
    for (int i = startIndex; i < endIndex; i++) {
        if (array[i] != null) {
            estimatedLength += array[i].toString().length();
        }
        // Add separator length for all but the last item
        if (i < endIndex - 1) {
            estimatedLength += separator.length();
        }
    }
    // A reasonable minimum to avoid very small initial capacities for empty or very short strings.
    // If estimatedLength is 0 (e.g., all nulls), start with a default capacity.
    StringBuilder buf = new StringBuilder(Math.max(16, estimatedLength));

    for (int i = startIndex; i < endIndex; i++) {
        if (i > startIndex) {
            buf.append(separator);
        }
        if (array[i] != null) {
            buf.append(array[i]);
        }
    }
    return buf.toString();
}
