        // --- Handle Numbers with Type Suffixes (l/L, f/F, d/D) ---
        final char lastChar = trimmedStr.charAt(trimmedStr.length() - 1);
        if (!Character.isDigit(lastChar) && lastChar != '.') { // Could be a suffix or malformed
            final String numericPart = trimmedStr.substring(0, trimmedStr.length() - 1);
            if (StringUtils.isBlank(numericPart)) {
