```java
public static String join(Object[] array, String separator, int startIndex, int endIndex) {
    if (array == null) {
        return null;
    }
    if (separator == null) {
        separator = ""; // Use literal "" for clarity, or refer to StringUtils.EMPTY if available
    }

    // Validate indices
    if (startIndex < 0 || startIndex > array.length) {
        throw new IndexOutOfBoundsException("startIndex must be within the bounds of the array: [0, " + array.length + "]. Given: " + startIndex);
    }
    if (endIndex < 0 || endIndex > array.length) {
        throw new IndexOutOfBoundsException("endIndex must be within the bounds of the array: [0, " + array.length + "]. Given: " + endIndex);
    }
    if (startIndex > endIndex) {
        throw new IllegalArgumentException("startIndex cannot be greater than endIndex. Given startIndex: " + startIndex + ", endIndex: " + endIndex);
    }

    int noOfItems = (endIndex - startIndex);
    if (noOfItems <= 0) {
        return ""; // Use literal "" for clarity, or refer to StringUtils.EMPTY if available
    }

    // Estimate initial capacity for StringBuilder to reduce reallocations.
    // A reasonable heuristic: average item length (e.g., 16) * number of items + (number of items - 1) * separator length.
    // This is an estimation; actual length might vary.
    int estimatedLength = 0;
    if (noOfItems > 0) {
        // Estimate for the first element
        estimatedLength += (array[startIndex] == null ? 16 : array[startIndex].toString().length());
        // Estimate for subsequent elements and separators
        estimatedLength += (noOfItems - 1) * (16 + separator.length());
    }
    // Ensure a minimum capacity to avoid very small initial buffers
    StringBuilder buf = new StringBuilder(Math.max(16, estimatedLength));

    for (int i = startIndex; i < endIndex; i++) {
        if (i > startIndex) {
            buf.append(separator);
        }
        if (array[i] != null) {
            buf.append(array[i]);
        }
    }
    return buf.toString();
}
