public static String join(Object[] array, String separator, int startIndex, int endIndex) {
    if (array == null) {
        return null;
    }
    if (separator == null) {
        separator = EMPTY;
    }

    // Adjust startIndex and endIndex to be within valid array bounds.
    // Ensure startIndex is not negative.
    int actualStartIndex = Math.max(0, startIndex);
    // Ensure endIndex does not exceed array length.
    int actualEndIndex = Math.min(array.length, endIndex);
    // Ensure startIndex does not exceed endIndex after adjustments.
    actualStartIndex = Math.min(actualStartIndex, actualEndIndex);

    int noOfItems = (actualEndIndex - actualStartIndex);
    if (noOfItems <= 0) {
        return EMPTY;
    }

    // Estimate initial capacity more robustly.
    // Assuming an average length of 16 for null or short objects,
    // plus the separator length for each item.
    // This is an heuristic, but better than just the first element.
    int initialCapacity = noOfItems * (16 + separator.length());
    StringBuilder buf = new StringBuilder(initialCapacity);

    for (int i = actualStartIndex; i < actualEndIndex; i++) {
        if (i > actualStartIndex) {
            buf.append(separator);
        }
        if (array[i] != null) {
            buf.append(array[i]);
        }
    }
    return buf.toString();
}
