        }

        // --- Handle Hexadecimal Numbers ---
        final String[] hexPrefixes = {"0x", "0X", "#"};
        final String[] negativeHexPrefixes = {"-0x", "-0X", "-#"};
        boolean isNegativeHex = false;
        String hexValue = null;

        for (final String pfx : hexPrefixes) {
            if (trimmedStr.startsWith(pfx)) {
                hexValue = trimmedStr.substring(pfx.length());
                break;
            }
        }
        if (hexValue == null) { // Check for negative hex prefixes
            for (final String pfx : negativeHexPrefixes) {
                if (trimmedStr.startsWith(pfx)) {
                    isNegativeHex = true;
                    hexValue = trimmedStr.substring(pfx.length());
                    break;
                }
            }
        }

