            if (StringUtils.isBlank(hexValue)) {
                throw new NumberFormatException(str + " is not a valid hexadecimal number (missing digits).");
            }
            // Validate hex digits - simple check if all are valid hex characters (0-9, a-f, A-F)
            for (char c : hexValue.toCharArray()) {
                if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) {
                    throw new NumberFormatException(str + " contains invalid hexadecimal digits.");
                }
            }

