        // Need to parse mantissa, decimal, and exponent parts
        String mantissa;
        String decimalPart = null;
        String exponentPart = null;

        int decPos = trimmedStr.indexOf('.');
        // Correctly find exponent position (case-insensitive)
        int expPos = -1;
        int expPosLowerE = trimmedStr.indexOf('e');
        int expPosUpperE = trimmedStr.indexOf('E');
        if (expPosLowerE > -1) {
            expPos = expPosLowerE;
        }
        if (expPosUpperE > -1) {
            if (expPos == -1 || expPosUpperE < expPos) { // Use the first 'e' or 'E' encountered
                expPos = expPosUpperE;
