        expPos = -1;
        expPosLowerE = numeric.indexOf('e');
        expPosUpperE = numeric.indexOf('E');
        if (expPosLowerE > -1) {
            expPos = expPosLowerE;
        }
        if (expPosUpperE > -1) {
            if (expPos == -1 || expPosUpperE < expPos) {
                expPos = expPosUpperE;
            }
        }

        // Parse mantissa, decimal part, and exponent part from the numeric string
        int numDecimals = 0;
        if (decPos > -1) { // There is a decimal point
            if (expPos > -1) { // There is an exponent
                decimalPart = numeric.substring(decPos + 1, expPos);
            } else {
                decimalPart = numeric.substring(decPos + 1);
            }
            mantissa = numeric.substring(0, decPos);
            numDecimals = decimalPart.length();
        } else {
            if (expPos > -1) {
                mantissa = numeric.substring(0, expPos);
            } else {
                mantissa = numeric;
            }
        }

        if (expPos > -1) {
            exponentPart = numeric.substring(expPos + 1);
        }

