                case 'd':
                case 'D':
                    try {
                        final Double d = createDouble(numeric);
                        final boolean allZeros = (isAllZeros(mantissa) && (decimalPart == null || isAllZeros(decimalPart)) && (exponentPart == null || isAllZeros(exponentPart)));
