                    }
                    // If Float/Double failed or lost precision, try BigDecimal
                    try {
                        return createBigDecimal(numeric);
                    } catch (final NumberFormatException e) {
                        // All attempts failed for this suffix
                        throw new NumberFormatException(str + " is not a valid number for type '" + lastChar + "'.");
                    }
                default: // Should not be reached due to previous hasSuffix check
                    throw new NumberFormatException(str + " is not a valid number.");
            }
        }

        // --- No Suffix - Determine Type Automatically ---
        // If no decimal point and no exponent, try Integer, then Long, then BigInteger
        if (decPos == -1 && expPos == -1) {
            try {
                return createInteger(numeric);
            } catch (final NumberFormatException nfe) {
                // Ignore, too big for Integer, try Long
            }
            try {
                return createLong(numeric);
            } catch (final NumberFormatException nfe) {
                // Ignore, too big for Long, try BigInteger
            }
            // If it's too big for Long or malformed as Long, createBigInteger will either succeed or throw
            return createBigInteger(numeric);
        }

        // Must be a Float, Double, or BigDecimal (has decimal or exponent)
        final boolean allZeros = (isAllZeros(mantissa) && (decimalPart == null || isAllZeros(decimalPart)) && (exponentPart == null || isAllZeros(exponentPart)));

        // Try Float first, if it can maintain precision
        try {
            // Heuristic for float precision: 7 or fewer decimal digits
            if (numDecimals <= 7) {
                final Float f = createFloat(numeric);
                if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                    return f;
                }
            }
