public static String join(Object[] array, String separator, int startIndex, int endIndex) {
    if (array == null) {
        return null;
    }
    if (separator == null) {
        separator = EMPTY;
    }

    // Validate indices
    if (startIndex < 0 || endIndex < 0) {
        throw new IndexOutOfBoundsException("startIndex and endIndex cannot be negative.");
    }
    if (startIndex > endIndex) {
        // This case is already handled by noOfItems <= 0, but can be made explicit.
        // For example, if array is {A, B, C}, startIndex=2, endIndex=1 should return empty.
        // The current logic correctly results in noOfItems = -1, returning EMPTY.
        // No change needed here, as the existing logic handles it gracefully.
    }
    if (startIndex >= array.length && array.length > 0) {
        // If startIndex is beyond array bounds (and array is not empty), it's invalid.
        // If array is empty, then startIndex=0, endIndex=0 is valid, returning empty.
        // If array is empty and startIndex > 0, it should also result in empty.
        // We ensure that if we intend to access array elements, the indices are valid.
        return EMPTY; // Or throw an IllegalArgumentException, depending on desired strictness.
    }
    // Ensure endIndex does not exceed array length, but it can be array.length (exclusive)
    if (endIndex > array.length) {
        endIndex = array.length; // Clip endIndex to array length
    }

    int noOfItems = (endIndex - startIndex);
    if (noOfItems <= 0) {
        return EMPTY;
    }

    // Estimate initial capacity for StringBuilder more accurately
    // Sum of lengths of all elements + sum of lengths of separators
    int estimatedCapacity = 0;
    if (noOfItems > 0) {
        for (int i = startIndex; i < endIndex; i++) {
            if (array[i] != null) {
                estimatedCapacity += array[i].toString().length();
            }
        }
        // Add length for separators: (noOfItems - 1) separators if noOfItems > 0
        estimatedCapacity += (noOfItems - 1) * separator.length();
    }

    StringBuilder buf = new StringBuilder(estimatedCapacity);

    for (int i = startIndex; i < endIndex; i++) {
        if (i > startIndex) {
            buf.append(separator);
        }
        if (array[i] != null) {
            buf.append(array[i]);
        }
    }
    return buf.toString();
}
