public static boolean isNumber(String str) {
    // Handle null or empty string
    if (str == null || str.isEmpty()) {
        return false;
    }

    char[] chars = str.toCharArray();
    int len = chars.length;
    boolean hasExp = false;
    boolean hasDecPoint = false;
    boolean allowSignsInExp = false; // Renamed from allowSigns for clarity
    boolean foundDigit = false;

    int i = 0; // Current character index

    // Deal with any possible sign up front for the whole number
    if (chars[0] == '-' || chars[0] == '+') {
        i++;
    }

    // Check for hexadecimal numbers
    if (len > i + 1 && chars[i] == '0' && (chars[i + 1] == 'x' || chars[i + 1] == 'X')) {
        int hexStart = i + 2;
        if (hexStart == len) {
            return false; // "0x" or "+0x" or "-0x" are not valid numbers
        }
        for (int k = hexStart; k < len; k++) {
            if (!((chars[k] >= '0' && chars[k] <= '9') ||
                  (chars[k] >= 'a' && chars[k] <= 'f') ||
                  (chars[k] >= 'A' && chars[k] <= 'F'))) {
                return false;
            }
        }
        return true;
    }

    // Process the rest of the string for decimal/exponential numbers
    // Loop through all characters
    for (; i < len; i++) {
        char c = chars[i];
        if (c >= '0' && c <= '9') {
            foundDigit = true;
            allowSignsInExp = false; // Digit cancels the need for an exponent sign
        } else if (c == '.') {
            if (hasDecPoint || hasExp) {
                // Two decimal points or decimal point after exponent
                return false;
            }
            hasDecPoint = true;
        } else if (c == 'e' || c == 'E') {
            if (hasExp || !foundDigit) {
                // Two 'E's or 'E' without a preceding digit
                return false;
            }
            hasExp = true;
            allowSignsInExp = true; // Allow sign immediately after 'e' or 'E'
            foundDigit = false; // Reset foundDigit to require a digit after 'e' or 'E'
        } else if (c == '+' || c == '-') {
            if (!allowSignsInExp) {
                // Sign not allowed here (e.g., in the middle of digits or before first digit)
                return false;
            }
            allowSignsInExp = false; // Sign consumed, no longer allowing another sign
            foundDigit = false; // Reset foundDigit to require a digit after the sign
        } else if (c == 'd' || c == 'D' || c == 'f' || c == 'F') {
            // Type qualifier for float/double. Must be the last character.
            // Also must have found a digit previously.
            // And cannot have an exponent (e.g., "1e5f" is valid, but "1e+f" is not)
            // (Note: "1e5f" means "1e5" followed by 'f', not "1e(5f)").
            // The logic here is tricky. A qualifier implies the *end* of the number.
            // If it's not the last char, it's invalid.
            if (i != len - 1 || !foundDigit || (hasExp && (chars[i-1] == '+' || chars[i-1] == '-'))) {
