                 // is to disallow cases like "1E+f" where 'f' is directly after an exponent sign
                 // without an intermediate digit.
                return false;
            }
            return true;
        } else if (c == 'l' || c == 'L') {
            // Type qualifier for long. Must be the last character.
            // Must have found a digit previously, and no exponent or decimal point.
            if (i != len - 1 || !foundDigit || hasExp || hasDecPoint) {
                return false;
            }
            return true;
        } else {
            // Any other character is invalid
            return false;
        }
    }

    // After iterating through all characters:
    // 1. Ensure at least one digit was found.
    // 2. Ensure we didn't end with an exponent sign ('E+') or just 'E'.
    return foundDigit && !allowSignsInExp;
