import org.apache.commons.lang3.StringUtils; // Assuming this dependency is available

public class NumberUtils {

    // ... (existing fields and other methods would be here) ...

    public static boolean isNumber(String str) {
        if (StringUtils.isEmpty(str)) {
            return false;
        }

        char[] chars = str.toCharArray();
        int len = chars.length;
        int start = 0;

        // Handle initial sign
        if (chars[0] == '-' || chars[0] == '+') {
            start = 1;
        }

        // Handle hexadecimal prefix "0x" or "0X"
        // This check must come AFTER initial sign if we want to support "-0x123"
        if (len > start + 1 && chars[start] == '0' && (chars[start + 1] == 'x' || chars[start + 1] == 'X')) {
            // Hexadecimal numbers cannot have decimal points, exponents, or type qualifiers (like f, d, l)
            // They can have a leading sign.
            int hexStart = start + 2;
            if (hexStart == len) {
                return false; // "0x" or "+0x" or "-0x"
            }
            for (int i = hexStart; i < len; i++) {
                char c = chars[i];
                if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) {
                    return false;
                }
            }
            return true;
        }

        // --- Standard Decimal/Float/Double Parsing ---
        boolean hasDecimalPoint = false;
        boolean hasExponent = false;
        boolean foundDigit = false;
        boolean allowSignForExponent = false; // True if we are after 'E' and before exponent digits

        int i = start;
        // Loop through the main body of the number
        while (i < len) {
            char c = chars[i];

            if (c >= '0' && c <= '9') {
                foundDigit = true;
                allowSignForExponent = false; // A digit invalidates expecting an exponent sign next
            } else if (c == '.') {
                if (hasDecimalPoint || hasExponent) {
                    return false; // Two decimal points or a decimal point after an exponent
                }
                hasDecimalPoint = true;
                allowSignForExponent = false; // A decimal point invalidates expecting an exponent sign next
            } else if (c == 'e' || c == 'E') {
                if (hasExponent || !foundDigit) {
                    return false; // Two exponents or an exponent without any preceding digits
                }
                hasExponent = true;
                foundDigit = false; // Reset foundDigit to require a digit *after* the 'E'
                allowSignForExponent = true; // Allow a sign for the exponent
            } else if (c == '+' || c == '-') {
                if (!allowSignForExponent) {
                    return false; // Sign only allowed at the beginning or immediately after 'e'/'E'
                }
                allowSignForExponent = false; // A sign has been consumed, don't allow another one right after
                foundDigit = false; // Reset foundDigit to require a digit *after* the exponent sign
            } else if (i == len - 1) { // Check for type qualifiers only if it's the last character
                if (c == 'f' || c == 'F' || c == 'd' || c == 'D') {
                    // Float/Double qualifiers. Requires a digit before it, and no pending exponent sign expectation.
                    // e.g., "1.0f", "1E1d". "1E+f" is invalid.
                    return foundDigit && !allowSignForExponent;
                } else if (c == 'l' || c == 'L') {
                    // Long qualifier. Requires a digit, no decimal, and no exponent.
                    return foundDigit && !hasDecimalPoint && !hasExponent;
                }
                return false; // Unknown character at the end
            } else {
                return false; // Unknown character in the middle
            }
            i++;
        }

        // After the loop, the string should have at least one digit and not be in a state
        // where an exponent digit or sign is expected.
        return foundDigit && !allowSignForExponent;
    }
}
