import java.io.IOException;
import java.io.Writer;

public class NumericEntityUnescaper extends org.apache.commons.lang3.text.translate.CodePointTranslator {

    @Override
    public int translate(CharSequence input, int index, Writer out) throws IOException {
        // Robustness: Handle null input gracefully if it were possible here, though generally assumed non-null
        // for CharSequenceTranslator. Assuming input is never null as per contract of parent class.

        // Robustness: Protect from ArrayIndexOutOfBounds at the beginning.
        // We need at least 4 characters for "&#X;", 3 for "&#1;" to be considered.
        // We need '&#', at least one character for the entity value, and a ';'.
        // So, minimum length of a valid entity is 4 (e.g., "&#1;").
        if (index >= input.length() - 3) { // Check if there's enough room for "&#1;" or "&#x;" (not 'x' itself, but minimum pattern)
            return 0;
        }

        if (input.charAt(index) == '&' && input.charAt(index + 1) == '#') {
            int start = index + 2;
            boolean isHex = false;

            // Robustness: Check if 'start' is within bounds before accessing.
            if (start >= input.length()) { // Malformed: ends with "&#"
                return 0;
            }

            char firstChar = input.charAt(start);
            if (firstChar == 'x' || firstChar == 'X') {
                start++;
                isHex = true;
                // Robustness: Check if 'start' is within bounds after incrementing for 'x'
                if (start >= input.length()) { // Malformed: ends with "&#x"
                    return 0;
                }
            }

            int end = start;
            // Robustness: Protect from infinite loop/ArrayIndexOutOfBounds if ';' is not found.
            // Loop until ';' or end of string.
            while (end < input.length() && input.charAt(end) != ';') {
                end++;
            }

            // Robustness: If ';' was not found, this is not a complete entity.
            if (end == input.length()) {
                return 0;
            }

            // Robustness: Ensure there's actual content between 'start' and 'end'.
            // For "&#;" or "&#x;" (after start increments), subSequence would be empty.
            if (start == end) {
                return 0; // No numeric value present (e.g., "&#;")
            }

            int entityValue;
            try {
                String numericPart = input.subSequence(start, end).toString();
                if (isHex) {
                    entityValue = Integer.parseInt(numericPart, 16);
                } else {
                    entityValue = Integer.parseInt(numericPart, 10);
                }
            } catch (NumberFormatException nfe) {
                return 0; // Not a valid number
            }

            // Robustness: Check for valid Unicode code point range.
            // Although Writer.write(int) handles surrogate pairs, a common convention for
            // numeric entities is to represent a single Unicode code point.
            // Valid code points are 0 to 0x10FFFF.
            if (entityValue < Character.MIN_CODE_POINT || entityValue > Character.MAX_CODE_POINT) {
                return 0; // Malformed entity value (out of Unicode range)
            }

            // Logic: Write the character corresponding to the parsed code point.
            out.write(entityValue);

            // Logic: Calculate consumed characters correctly.
            // 2 for "&#"
            // (end - start) for the numeric part
            // (isHex ? 1 : 0) for the 'x' if present
            // 1 for the trailing ';'
            return 2 + (end - start) + (isHex ? 1 : 0) + 1;
        }
        return 0; // Not a numeric entity starting with "&#"
    }
}
