public static int indexOfAnyBut(String str, String searchChars) {
    if (isEmpty(str)) {
        return INDEX_NOT_FOUND;
    }
    // Handle the specific case where searchChars is null or empty.
    // If searchChars is null or empty, *all* characters in str are "any but" the searchChars,
    // so the first character of str (at index 0) is the first match.
    if (isEmpty(searchChars)) {
        return 0;
    }

    // For better efficiency with potentially long searchChars,
    // convert searchChars to a Set for O(1) average lookup time.
    final int searchCharsLen = searchChars.length();
    final java.util.Set<Character> searchCharSet = new java.util.HashSet<>(searchCharsLen);
    for (int i = 0; i < searchCharsLen; i++) {
        searchCharSet.add(searchChars.charAt(i));
    }

    final int strLen = str.length();
    for (int i = 0; i < strLen; i++) {
        final char ch = str.charAt(i);
        // Check if the character is NOT present in the set of search characters
        if (!searchCharSet.contains(ch)) {
            return i;
        }
    }
    return INDEX_NOT_FOUND;
}
