public class ArrayUtils {

    // Assuming a private helper method exists as indicated by the original code
    // A simplified representation of what it might do:
    private static Object add(Object array, int index, Object element, Class<?> clss) {
        int newLength = (array == null ? 0 : Array.getLength(array)) + 1;
        Object newArray = Array.newInstance(clss, newLength);

        if (array != null) {
            System.arraycopy(array, 0, newArray, 0, index); // copy elements before index
            System.arraycopy(array, index, newArray, index + 1, Array.getLength(array) - index); // copy elements after index
        }
        Array.set(newArray, index, element); // insert the new element
        return newArray;
    }

    /**
     * Inserts an element into an array at a specified index.
     * This method creates a new array of the same component type as the original array,
     * or based on the element's type if the original array is null.
     * The element is inserted at the given index, shifting subsequent elements to the right.
     *
     * @param <T> The type of elements in the array.
     * @param array The array to insert the element into. Can be null, in which case a new array containing only the element is created.
     * @param index The index at which to insert the element. Must be between 0 and the length of the array (inclusive).
     * @param element The element to insert.
     * @return A new array with the element inserted at the specified index.
     * @throws IndexOutOfBoundsException if the index is out of bounds for the array (i.e., `index < 0` or `index > array.length`).
     * @throws IllegalArgumentException if both the array and element are null, as the component type cannot be determined.
     */
    public static <T> T[] add(T[] array, int index, T element) {
        Class<?> clss;
        int arrayLength = 0;

        if (array != null) {
            clss = array.getClass().getComponentType();
            arrayLength = array.length;
        } else {
            // array is null
            if (element != null) {
                clss = element.getClass();
            } else {
                // Both array and element are null. Cannot determine the component type.
                // Returning a generic Object[] is type-unsafe. Better to throw an exception.
                throw new IllegalArgumentException("Cannot determine component type when both array and element are null.");
            }
        }

        // Validate index after determining arrayLength (which is 0 if array is null)
        if (index < 0 || index > arrayLength) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Array Length: " + arrayLength);
        }

        @SuppressWarnings("unchecked") // The add method creates an array of type clss, which is type T
        final T[] newArray = (T[]) add(array, index, element, clss);
        return newArray;
    }
}
