import java.lang.reflect.Array;

public class ArrayUtils {

    // Assuming copyArrayGrow1 exists and is correctly implemented
    // private static Object copyArrayGrow1(Object array, Class<?> newArrayComponentType) { ... }

    /**
     * Internal helper to create a new array with one more element, copying existing elements.
     * This is a simplified version for demonstration, assuming the original `copyArrayGrow1`
     * from Apache Commons Lang is more robust.
     */
    private static Object copyArrayGrow1(Object array, Class<?> newArrayComponentType) {
        if (array == null) {
            return Array.newInstance(newArrayComponentType, 1);
        }
        int newLength = Array.getLength(array) + 1;
        Object newArray = Array.newInstance(newArrayComponentType, newLength);
        System.arraycopy(array, 0, newArray, 0, Array.getLength(array));
        return newArray;
    }

    /**
     * Creates a new array by adding the specified element to the end of the given array.
     * This method handles null input arrays and ensures proper type inference.
     *
     * @param <T> The type of elements in the array.
     * @param array The array to add the element to. Can be {@code null}.
     * @param element The element to add to the array. Can be {@code null}.
