     *         with the element as its only member is returned.
     *         If the input array is not {@code null}, a new array of the same component type as the input array is returned.
     */
    public static <T> T[] add(T[] array, T element) {
        Class<?> type;

        // Determine the component type of the new array.
        // Priority: existing array's component type, then element's class, then Object.class.
        if (array != null) {
            type = array.getClass().getComponentType();
        } else if (element != null) {
            type = element.getClass();
        } else {
            // Both array and element are null. Default to Object.class for the component type.
            type = Object.class;
        }

        // The copyArrayGrow1 method will create a new array instance of 'type' and
