public static boolean containsNone(CharSequence cs, char[] searchChars) {
    // If the character sequence to search is null or empty, it cannot contain any characters.
    // Thus, it contains none of the search characters.
    if (cs == null || cs.length() == 0) {
        return true;
    }
    // If the array of characters to search for is null or empty,
    // there are no characters to check against, so the sequence vacuously contains none.
    if (searchChars == null || searchChars.length == 0) {
        return true;
    }

    int csLen = cs.length();
    int searchLen = searchChars.length;

    // Iterate through each character in the input CharSequence.
    for (int i = 0; i < csLen; i++) {
        char ch = cs.charAt(i);
        // For each character in the input sequence, iterate through the array of search characters.
        for (int j = 0; j < searchLen; j++) {
            // If any character from the input sequence matches any character in the search array,
            // then the sequence *does* contain one of the search characters.
            // Therefore, the condition "contains none" is false.
            if (searchChars[j] == ch) {
                return false;
            }
        }
    }
    // If the loops complete without finding any matches, it means the CharSequence
    // contains none of the characters in the search array.
    return true;
}
