                if (hasDecPoint || hasExp) {
                    // Two decimal points, or a decimal point within an exponent part (e.g., "1E1.2")
                    return false;
                }
                hasDecPoint = true;
            } else if (chars[i] == 'e' || chars[i] == 'E') {
                if (hasExp) {
                    return false; // Two 'e' or 'E' characters
                }
                if (!foundDigit) {
                    // An 'e' or 'E' must be preceded by at least one digit (e.g., ".E1", "E1" are invalid)
                    return false;
                }
                hasExp = true;
                allowSigns = true; // A sign is allowed immediately after 'e'/'E' (e.g., "1e+5", "1e-5")
                foundDigit = false; // Reset foundDigit to ensure a digit follows the 'e' or 'E' (or its sign)
            } else if (chars[i] == '+' || chars[i] == '-') {
                if (!allowSigns) {
                    // Sign only allowed at the beginning or immediately after 'e'/'E'
                    return false;
                }
                allowSigns = false; // Consume the sign, no more signs immediately after
                foundDigit = false; // We need a digit after this sign in the exponent
            } else {
                return false; // Invalid character found
            }
            i++;
        }

        // --- Post-loop check for the last character (potential type qualifier or a digit) ---
        if (i < chars.length) { // If there's a character remaining after the loop
            if (chars[i] >= '0' && chars[i] <= '9') {
                // The last character is a digit, no type qualifier, this is a valid number.
                // This covers cases like "123", "1.23", "123e4"
                return foundDigit; // Ensure at least one digit was found overall
            }
            if (chars[i] == 'e' || chars[i] == 'E') {
                // An 'e' or 'E' cannot be the last character (e.g., "123E")
                return false;
            }
            if (!allowSigns && (chars[i] == 'd' || chars[i] == 'D' || chars[i] == 'f' || chars[i] == 'F')) {
                // 'd', 'D', 'f', 'F' qualifiers for floating-point numbers
                return foundDigit; // Must have at least one digit before the qualifier
            }
            if (chars[i] == 'l' || chars[i] == 'L') {
                // 'l', 'L' qualifier for long integers
                // A long cannot have a decimal point or an exponent
                return foundDigit && !hasExp && !hasDecPoint;
            }
            // Any other character at the end is illegal (e.g., "123G")
            return false;
        }

        // If the loop finished and there are no characters left, or the last char was handled
        // `allowSigns` being true here implies the number ends with 'e' or 'E' or 'e+' or 'e-', without a trailing digit.
        // `foundDigit` ensures that at least one digit was found at some point.
        return !allowSigns && foundDigit;
    }
}
