import org.apache.commons.lang3.StringUtils;

public class NumberUtils {

    // Existing fields and other methods are omitted for brevity,
    // as the request only focuses on the isNumber method.

    /**
     * <p>Checks whether the String a valid Java number.</p>
     *
     * <p>Valid numbers include hexadecimal numbers (e.g., "0xFF"), decimal numbers
     * with an optional decimal point and exponent (e.g., "123", "-1.23", "1E+5"),
     * and numbers with type qualifiers (e.g., "123L", "1.2f").</p>
     *
     * <p>This method does not support locale-specific decimal separators (always uses '.').</p>
     *
     * @param str the String to check
     * @return {@code true} if the String is a syntactically valid number, {@code false} otherwise.
     */
    public static boolean isNumber(String str) {
        if (StringUtils.isEmpty(str)) {
            return false;
        }

        char[] chars = str.toCharArray();
        int len = chars.length;
        boolean hasExp = false;
        boolean hasDecPoint = false;
        boolean allowSignsInExp = false; // Flag to allow '+' or '-' immediately after 'e'/'E'
        boolean foundDigit = false;

        int start = 0;
        // Deal with any possible sign up front
        if (chars[0] == '-' || chars[0] == '+') {
            start = 1;
        }

        // Handle potential "0x" for hexadecimal numbers
        if (len > start + 1 && chars[start] == '0' && chars[start + 1] == 'x') {
            int hexStart = start + 2;
            if (hexStart == len) {
                return false; // str == "0x" or "+0x" or "-0x"
            }
            // Checking hex (it can't be anything else if it starts with "0x")
            for (int i = hexStart; i < len; i++) {
                if (!((chars[i] >= '0' && chars[i] <= '9') ||
                        (chars[i] >= 'a' && chars[i] <= 'f') ||
                        (chars[i] >= 'A' && chars[i] <= 'F'))) {
                    return false;
                }
            }
            return true;
        }

        int i = start;
        while (i < len) {
            char c = chars[i];
            if (c >= '0' && c <= '9') {
                foundDigit = true;
                allowSignsInExp = false; // Reset for next segment if digit encountered
            } else if (c == '.') {
                if (hasDecPoint || hasExp) {
                    // Two decimal points or decimal in exponent
                    return false;
                }
                hasDecPoint = true;
            } else if (c == 'e' || c == 'E') {
                if (hasExp || !foundDigit) {
                    // Two 'e's or 'e' without any preceding digit
                    return false;
                }
                hasExp = true;
                allowSignsInExp = true; // Allow sign immediately after 'e'/'E'
                foundDigit = false; // Need a digit after the exponent sign (or 'e'/'E' itself if no sign)
            } else if (c == '+' || c == '-') {
                if (!allowSignsInExp) {
                    // Sign not allowed at this position (e.g., "1-2" or "1++2")
                    return false;
                }
                allowSignsInExp = false; // Sign consumed, no more signs allowed until another 'e'/'E'
                foundDigit = false; // Need a digit after the exponent sign
            } else {
                // If it's the last character, it could be a type qualifier
                if (i == len - 1) {
                    if (c == 'd' || c == 'D' || c == 'f' || c == 'F') {
                        return foundDigit; // Requires at least one digit (e.g., "1.2f", ".3f")
                    } else if (c == 'l' || c == 'L') {
                        // 'L' not allowed with an exponent or without digits
                        return foundDigit && !hasExp && !hasDecPoint; // L usually implies integer, no decimal or exponent
                    }
                }
                // Any other character, or a qualifier not at the end
                return false;
            }
            i++;
        }

        // After the loop, if we expected a digit after 'e'/'E' but didn't find one
        // or if no digits were found at all.
        return foundDigit && !allowSignsInExp;
    }
}
