        final boolean allZeros = isAllZeros(mant) && (exp == null || isAllZeros(exp));

        if (decPos == -1 && ePos == -1) { // No decimal point and no exponent -> Integer types
            try {
                return createInteger(trimmedStr);
            } catch (final NumberFormatException nfe) { /* ignore */ }
            try {
                return createLong(trimmedStr);
            } catch (final NumberFormatException nfe) { /* ignore */ }
            return createBigInteger(trimmedStr);
        } else { // Decimal point or exponent present -> Floating-point types
            try {
                final Float f = createFloat(trimmedStr);
                if (!f.isInfinite() && !(f.floatValue() == 0.0F && !allZeros)) {
