public static boolean toBoolean(String str) {
    if (str == null) {
        return false;
    }

    // Using equalsIgnoreCase for robust case-insensitive comparison
    // This handles "true", "TRUE", "True", "tRue", etc. correctly and efficiently.
    if (str.equalsIgnoreCase("true")) {
        return true;
    }

    // Handle "on" (case-insensitive)
    if (str.equalsIgnoreCase("on")) {
        return true;
    }

    // Handle "yes" (case-insensitive)
    if (str.equalsIgnoreCase("yes")) {
        return true;
    }

    // Explicitly handle common "false" string representations for clarity,
    // though for this specific method's original intent, any non-true string
    // defaults to false. This makes the intent clearer.
    if (str.equalsIgnoreCase("false") ||
        str.equalsIgnoreCase("off") ||
        str.equalsIgnoreCase("no") ||
        str.equals("0")) { // Assuming "0" is also considered false, typical for boolean conversion.
        return false;
    }

    // If none of the recognized "true" or "false" strings are matched,
    // the default behavior is to return false.
    return false;
}
