        }
    }

    public static synchronized FastDateFormat getDateInstance(int style, TimeZone timeZone, Locale locale) {
        // Ensure locale is never null for internal consistency and API calls
        Locale actualLocale = (locale == null) ? Locale.getDefault() : locale;

        // Use a custom, robust key for caching
        DateFormatKey key = new DateFormatKey(style, timeZone, actualLocale);

        FastDateFormat format = (FastDateFormat) cDateInstanceCache.get(key);
        if (format == null) {
            // Validate style upfront for clearer error messages
            if (style != DateFormat.FULL && style != DateFormat.LONG && style != DateFormat.MEDIUM && style != DateFormat.SHORT) {
                throw new IllegalArgumentException("Invalid date style: " + style + ". Must be one of DateFormat.FULL, LONG, MEDIUM, or SHORT.");
            }

            try {
                // DateFormat.getDateInstance uses SimpleDateFormat internally for these parameters
                SimpleDateFormat formatter = (SimpleDateFormat) DateFormat.getDateInstance(style, actualLocale);
                String pattern = formatter.toPattern();

                // Use the provided timeZone and the resolved actualLocale for creating the instance
                format = getInstance(pattern, timeZone, actualLocale);
                cDateInstanceCache.put(key, format);

            } catch (ClassCastException ex) {
                // This catch block indicates a severe, unexpected runtime environment issue.
                // The message should reflect the actual problem.
                throw new IllegalStateException("Unexpected ClassCastException when obtaining SimpleDateFormat. " +
                                                 "DateFormat.getDateInstance(style, locale) did not return a SimpleDateFormat. " +
                                                 "This may indicate an issue with the JVM or its DateFormat implementation.", ex);
            }
        }
        return format;
    }
