public static boolean toBoolean(String str) {
    if (str == null) {
        return false;
    }

    // Convert the string to lowercase once for case-insensitive comparisons
    // This is more robust and less error-prone than character-by-character checks.
    String lowerStr = str.toLowerCase();

    // Check for "true" related values
    if ("true".equals(lowerStr)) {
        return true;
    }
    if ("on".equals(lowerStr)) {
        return true;
    }
    if ("yes".equals(lowerStr)) {
        return true;
    }

    // Optionally, if explicit 'false' strings should be recognized.
    // For this specific method signature (toBoolean(String)),
    // the common convention is that anything not explicitly true is false.
    // If the intent was to recognize 'false' as well, it would be added here:
    // if ("false".equals(lowerStr) || "off".equals(lowerStr) || "no".equals(lowerStr)) {
    //     return false; // Redundant as it would fall through to false anyway, but explicit.
    // }

    // If none of the recognized "true" strings match, return false.
    return false;
}
