public StrBuilder appendFixedWidthPadRight(Object obj, int width, char padChar) {
    if (width < 0) {
        throw new IllegalArgumentException("Width must be non-negative.");
    }
    if (width == 0) {
        return this; // Appending nothing for a width of 0
    }

    ensureCapacity(size + width); // Ensure enough capacity for the fixed width

    String str = (obj == null ? getNullText() : obj.toString());
    // Ensure 'str' is not null, as getNullText() could potentially return null
    // though in practice for StrBuilder it usually returns "null".
    // Added defensive check here just in case custom getNullText() returns null.
    if (str == null) {
        str = ""; // Treat null text as empty string for padding purposes
    }

    int strLen = str.length();

    if (strLen >= width) {
        // Truncate the string if it's longer than or equal to the width
        str.getChars(0, width, buffer, size);
    } else {
        // Append the entire string
        str.getChars(0, strLen, buffer, size);
        // Pad the remaining length with padChar
        int padLen = width - strLen;
        for (int i = 0; i < padLen; i++) {
            buffer[size + strLen + i] = padChar;
        }
    }
    size += width; // Increment size by the fixed width
    return this;
}
