```java
public StrBuilder appendFixedWidthPadRight(Object obj, int width, char padChar) {
    if (width < 0) {
        throw new IllegalArgumentException("Width must not be negative");
    }
    if (width == 0) {
        return this; // No-op for zero width
    }

    ensureCapacity(size + width);
    String str = (obj == null ? getNullText() : obj.toString());
    int strLen = str.length();

    if (strLen >= width) {
        // Truncate the string to 'width' characters
        str.getChars(0, width, buffer, size);
    } else {
        // Append the string and then pad with 'padChar'
        int padLen = width - strLen;
        str.getChars(0, strLen, buffer, size);
        for (int i = 0; i < padLen; i++) {
            buffer[size + strLen + i] = padChar;
        }
    }
    // 'size' always increases by 'width' because we always append 'width' characters (string or padded string)
    size += width;
    return this;
}
