public static Locale toLocale(final String str) {
    if (str == null || str.isEmpty()) { // Handle empty string case as well
        return null;
    }

    final int len = str.length();

    // Language only: ll
    if (len == 2) {
        final char ch0 = str.charAt(0);
        final char ch1 = str.charAt(1);
        if (!Character.isLowerCase(ch0) || !Character.isLowerCase(ch1) || !Character.isLetter(ch0) || !Character.isLetter(ch1)) {
            throw new IllegalArgumentException("Invalid language code format: " + str + ". Must be two lowercase letters.");
        }
        return new Locale(str); // Locale(String language) is deprecated but works here. For modern Java, use Locale.forLanguageTag() or Locale.Builder
    }

    // Must be at least ll_X (5 chars) or ll_CC (5 chars)
    if (len < 5) {
        throw new IllegalArgumentException("Invalid locale format: " + str + ". Must be 'll', 'll_CC', 'll_CC_VV', or 'll__VV'.");
    }

    // Check for the first underscore separator
    if (str.charAt(2) != '_') {
        throw new IllegalArgumentException("Invalid locale format: " + str + ". Missing underscore separator after language code.");
    }

    final char ch0 = str.charAt(0);
    final char ch1 = str.charAt(1);
    if (!Character.isLowerCase(ch0) || !Character.isLowerCase(ch1) || !Character.isLetter(ch0) || !Character.isLetter(ch1)) {
        throw new IllegalArgumentException("Invalid language code format: " + str.substring(0, 2) + ". Must be two lowercase letters.");
    }

    final char ch3 = str.charAt(3);

    // Case: ll__VV (language and variant, no country)
    if (ch3 == '_') {
        // Variant must exist, cannot be just 'll__'
        if (len < 5) { // e.g., "en__"
            throw new IllegalArgumentException("Invalid locale format: " + str + ". Variant missing after 'll__'.");
        }
        // No further validation on variant characters is done, consistent with original
        return new Locale(str.substring(0, 2), "", str.substring(4));
    }

    // Case: ll_CC (language and country)
    final char ch4 = str.charAt(4);
    if (!Character.isUpperCase(ch3) || !Character.isUpperCase(ch4) || !Character.isLetter(ch3) || !Character.isLetter(ch4)) {
        throw new IllegalArgumentException("Invalid country code format: " + str.substring(3, 5) + ". Must be two uppercase letters.");
    }

    if (len == 5) {
        return new Locale(str.substring(0, 2), str.substring(3, 5));
    }

    // Case: ll_CC_VV (language, country, and variant)
    if (len < 7) { // e.g., "en_US_"
        throw new IllegalArgumentException("Invalid locale format: " + str + ". Variant missing after 'll_CC_'.");
    }
    if (str.charAt(5) != '_') {
        throw new IllegalArgumentException("Invalid locale format: " + str + ". Missing underscore separator after country code.");
    }

    // No further validation on variant characters is done, consistent with original
