public boolean contains(char ch) {
    // Obtain a local reference to the buffer for performance and thread safety (if applicable)
    char[] thisBuf = buffer;
    // Get the actual number of characters currently in the buffer
    int currentSize = size;

    // Check if the buffer itself is null or if the size is zero.
    // An empty StrBuilder (size 0) or a null buffer (though highly unlikely post-construction)
    // cannot contain any character.
    if (thisBuf == null || currentSize == 0) {
        return false;
    }

    // Iterate only up to the 'size' of the StrBuilder, not the full buffer capacity.
    // This ensures we only check actual content and avoid uninitialized parts.
    for (int i = 0; i < currentSize; i++) {
        if (thisBuf[i] == ch) {
            return true; // Character found
        }
    }
    return false; // Character not found after checking all relevant characters
}
